:root {
  /* Colors */
  --color-surface: #f9f9ff;
  --color-surface-dim: #cfdaf2;
  --color-surface-bright: #f9f9ff;
  --color-surface-container-lowest: #ffffff;
  --color-surface-container-low: #f0f3ff;
  --color-surface-container: #e7eeff;
  --color-surface-container-high: #dee8ff;
  --color-surface-container-highest: #d8e3fb;
  --color-on-surface: #111c2d;
  --color-on-surface-variant: #3d4947;
  --color-inverse-surface: #263143;
  --color-inverse-on-surface: #ecf1ff;
  --color-outline: #6d7a77;
  --color-outline-variant: #bcc9c6;
  --color-surface-tint: #006a61;

  --color-primary: #00685f;
  --color-primary-hover: #0F766E;
  --color-on-primary: #ffffff;
  --color-primary-container: #008378;
  --color-on-primary-container: #f4fffc;
  --color-inverse-primary: #6bd8cb;

  --color-secondary: #006c49;
  --color-on-secondary: #ffffff;
  --color-secondary-container: #6cf8bb;
  --color-on-secondary-container: #00714d;

  --color-tertiary: #0051d5;
  --color-on-tertiary: #ffffff;
  --color-tertiary-container: #316bf3;
  --color-on-tertiary-container: #fefcff;

  --color-error: #ba1a1a;
  --color-on-error: #ffffff;
  --color-error-container: #ffdad6;
  --color-on-error-container: #93000a;

  /* Typography */
  --font-family-display: 'Plus Jakarta Sans', sans-serif;
  --font-family-body: 'Inter', sans-serif;

  /* Spacing */
  --space-2xs: 0.25rem;
  --space-xs: 0.5rem;
  --space-sm: 0.75rem;
  --space-md: 1rem;
  --space-lg: 1.5rem;
  --space-xl: 2rem;
  --space-2xl: 3rem;
  --space-3xl: 4rem;
  --space-4xl: 6rem;
  --gutter-mobile: 1rem;
  --gutter-desktop: 1.5rem;
  --container-max: 80rem;

  /* Shapes */
  --rounded-sm: 0.25rem;
  --rounded-base: 0.5rem;
  --rounded-md: 0.75rem;
  --rounded-lg: 1rem;
  --rounded-xl: 1.5rem;
  --rounded-full: 9999px;

  /* Elevations */
  --shadow-level-1: 0 1px 3px 0 rgba(15, 23, 42, 0.04), 0 1px 2px -1px rgba(15, 23, 42, 0.04);
  --shadow-level-2: 0 10px 15px -3px rgba(15, 23, 42, 0.05), 0 4px 6px -4px rgba(15, 23, 42, 0.03);
  --shadow-level-3: 0 20px 25px -5px rgba(15, 23, 42, 0.07), 0 8px 10px -6px rgba(15, 23, 42, 0.03);
}

body {
  margin: 0;
  font-family: var(--font-family-body);
  background-color: var(--color-surface);
  color: var(--color-on-surface);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-family-display);
  color: var(--color-on-surface);
  margin-top: 0;
  margin-bottom: var(--space-md);
  letter-spacing: -0.02em;
}

h1 {
  font-size: 3.5rem;
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.03em;
}

@media (max-width: 768px) {
  h1 {
    font-size: 2.25rem;
    line-height: 1.2;
    letter-spacing: -0.02em;
  }
}

h2 {
  font-size: 2.25rem;
  font-weight: 600;
  line-height: 1.25;
}

h3 {
  font-size: 1.5rem;
  font-weight: 600;
  line-height: 1.35;
  letter-spacing: -0.01em;
}

p {
  margin-top: 0;
  margin-bottom: var(--space-md);
}

a {
  color: var(--color-primary);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

* {
  box-sizing: border-box;
}

.container {
  max-width: var(--container-max);
  margin: 0 auto;
  padding-left: var(--gutter-mobile);
  padding-right: var(--gutter-mobile);
}

@media (min-width: 1024px) {
  .container {
    padding-left: var(--space-3xl);
    padding-right: var(--space-3xl);
  }
}

/* Utilities */
.text-center { text-align: center; }
.flex { display: flex; }
.flex-col { display: flex; flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.justify-center { justify-content: center; }
.gap-sm { gap: var(--space-sm); }
.gap-md { gap: var(--space-md); }
.gap-lg { gap: var(--space-lg); }

/* Components */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-xs) var(--space-md);
  border-radius: var(--rounded-base);
  font-weight: 600;
  font-size: 0.875rem;
  cursor: pointer;
  transition: all 0.2s ease;
  border: none;
  font-family: var(--font-family-body);
}

.btn-primary {
  background-color: var(--color-primary);
  color: var(--color-on-primary);
}

.btn-primary:hover {
  background-color: var(--color-primary-hover);
}

.btn-primary:active {
  transform: scale(0.98);
}

.btn-outline {
  background-color: transparent;
  color: var(--color-on-surface);
  border: 1px solid var(--color-outline-variant);
}

.btn-outline:hover {
  background-color: var(--color-surface-container-lowest);
  color: var(--color-primary);
}

.card {
  background-color: var(--color-surface-container-lowest);
  border: 1px solid var(--color-outline-variant);
  border-radius: var(--rounded-xl);
  padding: var(--space-xl);
  box-shadow: var(--shadow-level-1);
  transition: all 0.2s ease;
}

.card:hover {
  box-shadow: var(--shadow-level-2);
  border-color: #CBD5E1;
}

.badge {
  display: inline-flex;
  align-items: center;
  padding: 2px var(--space-xs);
  border-radius: var(--rounded-full);
  font-size: 0.75rem;
  font-weight: 600;
}

.badge-success {
  background-color: #D1FAE5;
  color: #065F46;
}

.badge-info {
  background-color: #DBEAFE;
  color: #1E40AF;
}

