import React from 'react';

export const Button = ({ children, variant = 'primary', className = '', ...props }) => {
  const baseClass = 'btn';
  const variantClass = variant === 'primary' ? 'btn-primary' : 'btn-outline';

  return (
    <button className={`${baseClass} ${variantClass} ${className}`} {...props}>
      {children}
    </button>
  );
};

import React from 'react';

export const Badge = ({ children, variant = 'success', className = '' }) => {
  const baseClass = 'badge';
  const variantClass = variant === 'success' ? 'badge-success' : 'badge-info';

  return (
    <span className={`${baseClass} ${variantClass} ${className}`}>
      {children}
    </span>
  );
};

import React from 'react';

