        </div>

        {/* Desktop Nav */}
        <nav style={{ display: 'flex', gap: 'var(--space-lg)' }} className="hidden md:flex">
          <a href="#services" style={{ color: 'var(--color-on-surface-variant)', fontWeight: 500 }}>Services</a>
          <a href="#vets" style={{ color: 'var(--color-on-surface-variant)', fontWeight: 500 }}>Our Vets</a>
