      paddingTop: 'var(--space-4xl)', 
      paddingBottom: 'var(--space-4xl)',
      backgroundColor: 'var(--color-surface)',
      textAlign: 'center'
    }}>
      <div className="container flex-col items-center gap-md">
        <Badge variant="success" className="mb-sm">Trusted by 10,000+ Pet Parents</Badge>

        <h1 style={{ maxWidth: '800px', margin: '0 auto', marginBottom: 'var(--space-md)' }}>
          Exceptional Care for Your Furry Friends
        </h1>

        <p style={{ 
          fontSize: '1.125rem', 
          color: 'var(--color-on-surface-variant)', 
          maxWidth: '600px', 
          margin: '0 auto',
          marginBottom: 'var(--space-xl)'
        }}>
          Experience clinical-grade, compassionate veterinary care from the comfort of your home. Book video consultations, manage medical records, and ensure your pet's lifelong wellness.
        </p>

        <div className="flex justify-center gap-md" style={{ flexWrap: 'wrap' }}>
