  const servicesList = [
    {
      title: 'Online Video Consultations',
      description: 'Connect with certified veterinarians instantly for advice, triaging, and follow-ups without the stress of clinic visits.',
      icon: '🩺'
    },
    {
      title: 'Digital Health Records',
      description: 'Keep all your pet\'s medical history, vaccination charts, and prescriptions securely in one accessible place.',
      icon: '📋'
    },
    {
      title: 'Wellness & Prevention',
      description: 'Customized diet plans, routine reminders, and preventative care strategies tailored to your pet\'s breed and age.',
      icon: '🛡️'
    }
  ];

  return (
    <section id="services" style={{ 
      paddingTop: 'var(--space-4xl)', 
      paddingBottom: 'var(--space-4xl)',
      backgroundColor: 'var(--color-surface-container-low)'
    }}>
      <div className="container">
        <div style={{ textAlign: 'center', marginBottom: 'var(--space-3xl)' }}>
          <h2 style={{ marginBottom: 'var(--space-xs)' }}>Our Clinical Services</h2>
          <p style={{ color: 'var(--color-on-surface-variant)', maxWidth: '600px', margin: '0 auto' }}>
            We bring modern veterinary medicine directly to you, combining high-stakes precision with compassionate, everyday pet wellness.
          </p>
        </div>

        <div style={{ 
          display: 'grid', 
          gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', 
          gap: 'var(--space-xl)' 
        }}>
          {servicesList.map((svc, idx) => (
            <Card key={idx} className="flex-col gap-sm">
              <div style={{ 
                fontSize: '2rem', 
                backgroundColor: 'var(--color-surface-container)', 
                width: '64px', 
                height: '64px', 
                display: 'flex', 
                alignItems: 'center', 
                justifyContent: 'center',
                borderRadius: 'var(--rounded-lg)',
                marginBottom: 'var(--space-sm)'
              }}>
                {svc.icon}
              </div>
              <h3 style={{ marginBottom: 'var(--space-2xs)' }}>{svc.title}</h3>
              <p style={{ color: 'var(--color-on-surface-variant)', marginBottom: 0, fontSize: '0.95rem' }}>
                {svc.description}
              </p>
            </Card>
          ))}
        </div>
      </div>
    </section>
  );
};

